sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }

	var ga = new GlideAjax('x_1305322_learns_0.LearnSphereDuplicate');
	ga.addParam('sysparm_name', 'getDuplicateSchedule');
	if (newValue != '') {
		ga.addParam('sysparm_scheduleName', g_form.getValue('name'));
		ga.getXML(duplicate);
	}

	function duplicate(response) {
		var result = response.responseXML.documentElement.getAttribute("answer");
		if (result == 'true') {
			g_form.addErrorMessage("This schedule '" + g_form.getValue('name') + "' already exist!");
			g_form.setValue('date', '');
			g_form.setValue('course', '');
			g_form.setValue('name', '');
		}
	}
   //Type appropriate comment here, and begin script below

}
